import AppKit

/// Remembers the last few links the user copied — in memory only, never written to disk.
@MainActor
final class ClipboardWatcher: ObservableObject {
    static let limit = 10

    /// Newest first.
    @Published private(set) var links: [String] = []

    private var timer: Timer?
    private var lastChangeCount = -1

    /// Markers password managers put on secrets (see nspasteboard.org).
    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    /// Belt and braces: never record anything copied while a password manager is frontmost.
    private static let ignoredApps: Set<String> = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "com.apple.Passwords",
        "com.apple.keychainaccess",
        "in.sinew.Enpass-Desktop",
        "com.dashlane.dashlanephonefinal",
        "org.keepassxc.keepassxc",
    ]

    func setEnabled(_ enabled: Bool) {
        if enabled {
            guard timer == nil else { return }
            let timer = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
                MainActor.assumeIsolated { self?.poll() }
            }
            RunLoop.main.add(timer, forMode: .common)
            self.timer = timer
        } else {
            timer?.invalidate()
            timer = nil
            lastChangeCount = -1
            links.removeAll()
        }
    }

    /// Forgets remembered links. The current clipboard isn't re-added until something new is copied.
    func clear() {
        links.removeAll()
    }

    private func poll() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount

        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.ignoredTypes) else { return }
        if let app = NSWorkspace.shared.frontmostApplication?.bundleIdentifier, Self.ignoredApps.contains(app) {
            return
        }
        guard let link = Self.link(from: pasteboard.string(forType: .string)) else { return }

        links.removeAll { $0 == link }
        links.insert(link, at: 0)
        if links.count > Self.limit {
            links.removeLast(links.count - Self.limit)
        }
    }

    /// The whole clipboard must be a single http(s) link; anything else is ignored.
    static func link(from string: String?) -> String? {
        guard let s = string?.trimmingCharacters(in: .whitespacesAndNewlines),
              !s.isEmpty, s.count <= 2000, !s.contains(where: \.isWhitespace),
              let url = URL(string: s),
              let scheme = url.scheme?.lowercased(), scheme == "http" || scheme == "https",
              url.host != nil
        else { return nil }
        return s
    }

    /// Compact chip label: "x.com/user/status/12…".
    static func shortLabel(for link: String) -> String {
        guard let url = URL(string: link), var host = url.host else { return link }
        if host.hasPrefix("www.") { host.removeFirst(4) }
        let path = url.path == "/" ? "" : url.path
        let label = host + path
        return label.count > 28 ? String(label.prefix(27)) + "…" : label
    }
}
